			        t: t,
			        store: storeRef,
			        actions: actions,
			        zoom: zoom,
			        pan: pan,
			        cardPos: cardPos,
			        sel: sel,
			        setSel: setSel,
			        linking: linking,
			        setLinking: setLinking,
			        setZoom: setZoom,
